  1	import type { IncomingMessage, ServerResponse } from 'node:http';
  2	import type { Router } from '../router.js';
  3	import type { AppConfig, GitCredentialEntry } from '../../config/config.types.js';
  4	import type { PollingManager } from '../pollingManager.js';
  5	import type { ErrorLogManager } from '../../error-log/error-log.manager.js';
  6	import { saveConfigField } from '../../config/config.js';
  7	import { parseJsonBody, sendJson, sendError, isPlainObject } from '../requestUtils.js';
  8	import { toKebabCase } from '../../utils/slug.js';
  9	
 10	// Polling-interval bounds — shared with settings UI (gui/public/js/views/settings.js).
 11	import {
 12	    MIN_POLLING_INTERVAL_SECONDS,
 13	    MAX_POLLING_INTERVAL_SECONDS,
 14	    MIN_NOTES_CARD_HEIGHT,
 15	    MAX_NOTES_CARD_HEIGHT,
 16	    MIN_NOTES_COLUMNS,
 17	    MAX_NOTES_COLUMNS,
 18	    MAX_CREDENTIAL_ID_LENGTH,
 19	    MAX_CREDENTIAL_LABEL_LENGTH,
 20	    MAX_CREDENTIAL_HOST_LENGTH,
 21	    MAX_CREDENTIAL_TOKEN_LENGTH,
 22	} from '../../config/config.constants.js';
 23	
 24	// ---------------------------------------------------------------------------
 25	// Helpers
 26	// ---------------------------------------------------------------------------
 27	
 28	/**
 29	 * Masks a credential token for display in API responses.
 30	 * Shows the last 4 characters of the token prefixed with `****`.
 31	 * Tokens shorter than 4 characters are fully masked as `****`.
 32	 */
 33	function maskToken(token: string): string {
 34	    return token.length < 4 ? '****' : '****' + token.slice(-4);
 35	}
 36	
 37	/**
 38	 * Extracts and lowercases the scheme from a URL string (the part before the
 39	 * first `:`). Returns an empty string when no colon is present.
 40	 *
 41	 * @example extractScheme('https://example.com') // → 'https'
 42	 * @example extractScheme('javascript:alert(1)') // → 'javascript'
 43	 */
 44	function extractScheme(url: string): string {
 45	    const colonIdx = url.indexOf(':');
 46	    return colonIdx !== -1 ? url.slice(0, colonIdx).toLowerCase() : '';
 47	}
 48	
 49	/**
 50	 * Type guard that returns `true` when `value` is a finite integer number.
 51	 * Used by PUT route handlers to validate numeric config fields.
 52	 *
 53	 * @param value - The value to test (any type accepted).
 54	 * @returns `true` when `value` is of type `number`, finite, and an integer; `false` otherwise.
 55	 */
 56	function isValidFiniteInteger(value: unknown): value is number {
 57	    return typeof value === 'number' && Number.isFinite(value) && Number.isInteger(value);
 58	}
 59	
 60	/**
 61	 * Returns a copy of the credentials array with all tokens masked.
 62	 */
 63	function buildMaskedCredentials(
 64	    credentials: GitCredentialEntry[] | undefined,
 65	): GitCredentialEntry[] {
 66	    if (!credentials) return [];
 67	    return credentials.map((entry) => ({ ...entry, token: maskToken(entry.token) }));
 68	}
 69	
 70	/**
 71	 * Generates a unique kebab-case ID from a label, appending a numeric suffix
 72	 * (-2, -3, ...) when the base ID is already taken.
 73	 *
 74	 * @param label - The human-readable label to derive an ID from.
 75	 * @param existingIds - The set of IDs already in use; the returned ID is
 76	 *   guaranteed not to be a member of this set.
 77	 * @returns A kebab-case string ID that is unique within `existingIds`.
 78	 *
