 93	    let candidateId = baseId;
 94	    let suffix = 2;
 95	    while (existingIds.has(candidateId)) {
 96	        candidateId = `${baseId}-${suffix}`;
 97	        suffix++;
 98	    }
 99	    return candidateId;
100	}

