119	/**
120	 * Parses a numeric config field, enforcing integer-only values and optional
121	 * `[min, max]` range bounds.
122	 *
123	 * - If `value` is not a `number`, returns `defaultValue`.
124	 * - If `value` is a number but not an integer (e.g. a float like `220.5`),
125	 *   returns `defaultValue`.
126	 * - If `min` and `max` are provided and the integer value is outside that range,
127	 *   emits `console.warn` but returns the value as-is (no clamping).
128	 *
129	 * @param value     Raw value read from the config file.
130	 * @param fieldName Field name used in warning messages.
131	 * @param defaultValue Fallback value for non-numeric or float inputs.
132	 * @param min       Optional lower bound (inclusive).
133	 * @param max       Optional upper bound (inclusive).
134	 */
135	function parseIntegerField(
136	    value: unknown,
137	    fieldName: string,
138	    defaultValue: number,
139	    min?: number,
140	    max?: number,
141	): number {
142	    if (typeof value !== 'number') {
143	        return defaultValue;
144	    }
145	    if (!Number.isInteger(value)) {
146	        return defaultValue;
147	    }
148	    if (min !== undefined && max !== undefined && (value < min || value > max)) {
149	        console.warn(
150	            `Configuration warning: "${fieldName}" value ${value} is outside the allowed range ` +
151	            `[${min}, ${max}]. The value will be used as-is.`
152	        );
153	    }
154	    return value;
155	}
