364	            Severity: 'warning',
365	            Source: 'credential-audit',
366	            Operation: 'delete-credential',
367	            Context: {},
368	            Message: `Credential "${deletedEntry.id}" (label: "${deletedEntry.label}", host: "${deletedEntry.host}") was deleted.`,
369	        });
370	
371	        sendJson(res, 200, buildMaskedCredentials(appConfig.gitCredentials));
372	    });
