425	        if (seconds > MAX_POLLING_INTERVAL_SECONDS) {
426	            sendError(
427	                res,
428	                400,
429	                `Field "seconds" must be at most ${MAX_POLLING_INTERVAL_SECONDS} (24 hours). Received: ${seconds}.`,
430	            );
431	            return;
432	        }
433	
434	        // Update in-memory config.
435	        appConfig.gitPollingIntervalSeconds = seconds;
436	
437	        // Persist to disk.
438	        saveConfigField('gitPollingIntervalSeconds', seconds, configPath);
439	
