291	/**
292	 * Reads `config.json`, sets or removes a single top-level field, and writes the
293	 * file back via `writeJsonFile()`. All other fields — including `_instructions`
294	 * — are preserved.
295	 *
296	 * @param field - The top-level key to modify (e.g. `"gitCredentials"`).
297	 * @param value - The value to set, or `undefined` to remove the field.
298	 * @param configPath - Optional absolute path to the config file. Defaults to
299	 *   the tool-root `config.json`.
300	 * @throws {Error} If `config.json` cannot be read or written.
301	 */
302	export function saveConfigField(
303	    field: string,
304	    value: unknown,
305	    configPath?: string,
306	): void {
307	    const resolvedConfigPath = configPath ?? getConfigPath();
308	    const raw = readJsonFile<Record<string, unknown>>(resolvedConfigPath);
309	
310	    if (value === undefined) {
311	        delete raw[field];
312	    } else {
313	        raw[field] = value;
314	    }
315	
316	    writeJsonFile(resolvedConfigPath, raw);
317	
318	    // config.json may contain plaintext PATs in gitCredentials — restrict
319	    // file permissions to owner-only on POSIX systems.
320	    if (process.platform !== 'win32') {
321	        chmodSync(resolvedConfigPath, 0o600);
322	    }
323	}

